import{mountTeacherAdmin}from './teacher-admin.js';
import{ownerClassroomCall}from './owner-classroom.js';
import{staffIcon}from './staff-markup.js';
const icon=kind=>({home:'house.svg',teachers:'book.svg',tools:'gear.svg'}[kind]?'<img src="assets/'+({home:'house.svg',teachers:'book.svg',tools:'gear.svg'}[kind])+'" alt="" aria-hidden="true">':staffIcon(({users:'team',activity:'audit',materials:'publications'}[kind])||kind));
export function mountOwnerWorkspace(app,{isActive=()=>app.isConnected,onSelect=()=>{}}={}){
 const doc=app.ownerDocument,main=app.querySelector('.admin-intro'),nav=app.querySelector('.owner-sections');if(!main||!nav)throw Error('Кабинет пока недоступен.');main.classList.add('owner-workspace');
 const names={home:'Кабинет владельца',overview:'Обзор',users:'Пользователи',activity:'Активность',teachers:'Преподаватели',team:'Сотрудники',tools:'Система'};
 for(const[view,label]of [['home','Кабинет'],['teachers','Преподаватели'],['team','Сотрудники'],['tools','Система']]){const tab=doc.createElement('button');tab.type='button';tab.id='owner-tab-'+view;tab.dataset.view=view;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','owner-panel-'+view);tab.textContent=label;view==='home'?nav.prepend(tab):nav.append(tab);const panel=doc.createElement('div');panel.className='owner-view';panel.id='owner-panel-'+view;panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);main.append(panel);}
 for(const tab of nav.querySelectorAll('[data-view]')){const label=doc.createElement('span');label.className='owner-nav-label';while(tab.firstChild)label.append(tab.firstChild);const glyph=doc.createElement('span');glyph.className='owner-nav-icon';glyph.innerHTML=icon(tab.dataset.view==='overview'?'activity':tab.dataset.view);tab.append(glyph,label);}
 const tiles=[['overview','Обзор','Главное в SALAH','activity'],['users','Пользователи','Аккаунты и активность','users'],['team','Сотрудники','Роли и доступ','team','team'],['team','Сообщения','Личные и общий чат','messages','messages'],['teachers','Преподаватели','Назначения по нику','teachers'],['team','Материалы','Чтецы и оформление','materials','publications'],['team','Проверка','Предложения команды','review','review'],['activity','Посещения','Статистика сайта','activity'],['tools','Система','Диагностика и история','tools']];
 const home=app.querySelector('#owner-panel-home');home.innerHTML='<div class="owner-menu-grid">'+tiles.map(([view,label,detail,glyph,tab])=>'<button type="button" class="owner-menu-tile" data-owner-go="'+view+'"'+(tab?' data-owner-team-tab="'+tab+'"':'')+'>'+icon(glyph)+'<span><strong>'+label+'</strong><small>'+detail+'</small></span></button>').join('')+'</div>';
 const support=app.querySelector('.owner-support-link');if(support){support.className='owner-menu-tile owner-support-link';support.innerHTML=icon('messages')+'<span><strong>Поддержка</strong><small>Обращения пользователей</small></span><span class="support-state-dot" data-owner-support-status hidden></span>';home.querySelector('.owner-menu-grid').append(support);}
 const bar=doc.createElement('div');bar.className='owner-screenbar';bar.hidden=true;bar.innerHTML='<button type="button" aria-label="В кабинет владельца">'+staffIcon('back')+'</button><h1 tabindex="-1"></h1>';main.before(bar);
 const tools=app.querySelector('#owner-panel-tools');tools.innerHTML='<header class="owner-section-heading"><p>Диагностика и история изменений.</p></header>';for(const element of [app.querySelector('.owner-error-summary'),app.querySelector('.owner-release-history')])if(element)tools.append(element);
 let stopTeachers=null;let current='',disposed=false,module=null,epoch=0,loadedTab=null,pendingTab=null,lastLauncher=null;let room=new URLSearchParams(location.hash.split('?')[1]||'').get('room');const host=app.querySelector('#owner-panel-team');host.classList.add('owner-team-embed');
 const go=(view,tab=null)=>{pendingTab=tab;if(onSelect(view)===false){pendingTab=null;return;}const params=new URLSearchParams();if(view!=='home')params.set('view',view);if(view==='team'&&tab)params.set('tab',tab);if(view==='team'&&room)params.set('room',room);const hash='#admin'+(params.size?'?'+params:'');if(location.hash!==hash){window.history.pushState(window.history.state,'',hash);window.dispatchEvent(new Event('salah:route-history'));}pendingTab=null;window.scrollTo?.({top:0,left:0,behavior:'instant'});(view==='home'?(lastLauncher||home.querySelector('button')):bar.querySelector('h1')).focus({preventScroll:true});};
 home.querySelectorAll('[data-owner-go]').forEach(button=>button.onclick=()=>{lastLauncher=button;go(button.dataset.ownerGo,button.dataset.ownerTeamTab||null);});bar.querySelector('button').onclick=()=>go('home');
 const message=e=>{room=e.detail?.room||null;go('team','messages');};window.addEventListener('salah:staff-message-open',message);
 const pop=()=>{if(location.hash.split('?')[0]==='#admin'){const target=new URLSearchParams(location.hash.split('?')[1]||'').get('view')||'home';if(target==='profile')return;onSelect(Object.hasOwn(names,target)?target:'home');}};window.addEventListener('popstate',pop);
 return{navigate:go,canLeave(next){return next===current||current!=='team'||!module?.staffCabinetBusy()||window.confirm('Перейти без сохранения изменений команды?');},select(view){if(disposed||!isActive())return;const params=new URLSearchParams(location.hash.split('?')[1]||''),tab=pendingTab||params.get('tab')||'team';if(current==='team'&&(view!=='team'||tab!==loadedTab)){epoch++;module?.stopStaffCabinet();host.replaceChildren();current='';}if(view==='team'&&current!=='team'){loadedTab=tab;const version=++epoch;host.innerHTML='<p role="status">Открываем раздел…</p>';void import('./staff-cabinet.js').then(m=>{if(disposed||!isActive()||version!==epoch)return;module=m;return m.showStaffCabinet(host,{embedded:true,initialRoom:room,initialTab:tab,isActive:()=>!disposed&&current==='team'&&isActive()});}).catch(()=>{if(!disposed&&version===epoch)host.innerHTML='<p role="alert">Раздел пока недоступен. Откройте его ещё раз.</p>';});}
  if(current==='teachers'&&view!=='teachers'){stopTeachers?.();stopTeachers=null;}
  if(view==='teachers'&&current!=='teachers')stopTeachers=mountTeacherAdmin(app.querySelector('#owner-panel-teachers'),{call:ownerClassroomCall,isActive:()=>!disposed&&current==='teachers'&&isActive()});
  current=view;app.dataset.ownerView=view;app.classList.toggle('owner-section-open',view!=='home');bar.hidden=view==='home';bar.querySelector('h1').textContent=view==='team'?({team:'Сотрудники',messages:'Сообщения',publications:'Материалы',review:'Проверка',audit:'История команды'}[tab]||'Команда'):names[view];const periods=app.querySelector('#owner-periods');if(view==='overview')app.querySelector('#owner-statistics').prepend(periods);else if(view==='activity')app.querySelector('#owner-panel-activity .owner-chart-heading').after(periods);
 },dispose(){disposed=true;stopTeachers?.();stopTeachers=null;epoch++;module?.stopStaffCabinet();window.removeEventListener('salah:staff-message-open',message);window.removeEventListener('popstate',pop);bar.remove();main.classList.remove('owner-workspace');app.classList.remove('owner-section-open','owner-profile-open');delete app.dataset.ownerView;}};
}
